  AUTH_INVALID: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'user',
    action: { kind: 'open-settings', target: 'permissions' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'conversation' },
  },
  NETWORK: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  CONFIG: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'configuration' },
  },
  GATEWAY: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  BILLING: {
    retryable: false,
    scope: 'user',
    action: { kind: 'contact-support', target: 'billing' },
  },
  OVERLOADED: {
