  | 'UNKNOWN';

/**
 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** Who is permitted to perform the recovery represented by an error class. */
export type ErrorRecoveryScope = 'self' | 'user';

/**
 * A recovery is a closed, declarative vocabulary. Targets identify a bounded
 * settings area; they never contain user-provided or executable instructions.
 */
export type AppErrorNextAction =
  | { kind: 'retry' }
  | { kind: 'reauthenticate'; target: 'authentication' }
  | { kind: 'reconfigure'; target: 'configuration' | 'conversation' | 'model' }
  | { kind: 'open-settings'; target: 'billing' | 'permissions' }
  | { kind: 'contact-support'; target: 'billing' | 'configuration' };

export type AppErrorRecovery = {
  retryable: boolean;
  scope: ErrorRecoveryScope;
  action?: AppErrorNextAction;
};

/**
 * Stable recovery policy for every error class.
 *
 * The type makes omissions a compile-time error. Only transient classes that
 * can safely be retried by the application are self-scoped and retryable.
 * UNKNOWN deliberately has no action: its original message and cause remain
 * available to the unified error renderer for diagnosis.
 */
export const APP_ERROR_RECOVERY = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'user',
    action: { kind: 'open-settings', target: 'permissions' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'conversation' },
  },
  NETWORK: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  CONFIG: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'configuration' },
  },
  GATEWAY: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  BILLING: {
    retryable: false,
    scope: 'user',
    action: { kind: 'contact-support', target: 'billing' },
  },
  OVERLOADED: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  MODEL_NOT_FOUND: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'model' },
  },
  UNKNOWN: {
    retryable: false,
    scope: 'user',
  },
} as const satisfies Record<AppErrorCode, AppErrorRecovery>;

export class AppError extends Error {
  code: AppErrorCode;
  cause?: unknown;
  details?: Record<string, unknown>;
  /** Renderer-side correlation id echoed by the Main host dispatcher. */
  requestId?: string;
  retryable: boolean;
  nextAction?: AppErrorNextAction;

  constructor(
    code: AppErrorCode,
    message: string,
    cause?: unknown,
    details?: Record<string, unknown>,
    requestId?: string,
  ) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.cause = cause;
    this.details = details;
    this.requestId = requestId;
    const recovery = APP_ERROR_RECOVERY[code];
    this.retryable = recovery.retryable;
    this.nextAction = recovery.action;
  }
}

/**
 * Structured facts read off the thrown value and its cause/response chain.
 *
 * Classification reads these first; it only falls back to the raw technical
 * message when none of them identify a class. A user-facing string that has
 * already been translated is never a classification input (issue #120), so
 * changing the display language can never change the class.
 */
export type ErrorSignals = {
  code?: string;
  status?: number;
  reason?: string;
};

/**
 * Provider `code`/`reason`/`type` tokens (normalized to upper case) mapped to a
 * class. One table serves both structured fields so the two can never drift.
 */
const CODE_SIGNALS: Record<string, AppErrorCode> = {
  TIMEOUT: 'TIMEOUT',
  REQUEST_TIMEOUT: 'TIMEOUT',
  PERMISSION: 'PERMISSION',
  PERMISSION_ERROR: 'PERMISSION',
  FORBIDDEN: 'PERMISSION',
  PERMISSION_DENIED: 'PERMISSION',
  GATEWAY: 'GATEWAY',
  VALIDATION: 'CONFIG',
  INVALID_REQUEST: 'CONFIG',
  INVALID_REQUEST_ERROR: 'CONFIG',
  UNSUPPORTED: 'CHANNEL_UNAVAILABLE',
  CHANNEL_UNAVAILABLE: 'CHANNEL_UNAVAILABLE',
  CONVERSATION_STATE: 'CONVERSATION_STATE',
  INVALID_CONVERSATION_STATE: 'CONVERSATION_STATE',
  NETWORK: 'NETWORK',
  CONNECTION_ERROR: 'NETWORK',
  AUTH_INVALID: 'AUTH_INVALID',
  UNAUTHORIZED: 'AUTH_INVALID',
  AUTH_EXPIRED: 'AUTH_INVALID',
  AUTHENTICATION_ERROR: 'AUTH_INVALID',
  AUTH_PERMANENT: 'AUTH_PERMANENT',
  INVALID_API_KEY: 'AUTH_PERMANENT',
  API_KEY_INVALID: 'AUTH_PERMANENT',
  KEY_REVOKED: 'AUTH_PERMANENT',
  RATE_LIMIT: 'RATE_LIMIT',
  RATE_LIMITED: 'RATE_LIMIT',
  RATE_LIMIT_EXCEEDED: 'RATE_LIMIT',
  TOO_MANY_REQUESTS: 'RATE_LIMIT',
  BILLING: 'BILLING',
  PAYMENT_REQUIRED: 'BILLING',
  INSUFFICIENT_BALANCE: 'BILLING',
  INSUFFICIENT_QUOTA: 'BILLING',
  QUOTA_EXCEEDED: 'BILLING',
  BILLING_HARD_LIMIT_REACHED: 'BILLING',
  OVERLOADED: 'OVERLOADED',
  OVERLOADED_ERROR: 'OVERLOADED',
  MODEL_OVERLOADED: 'OVERLOADED',
  SERVER_OVERLOADED: 'OVERLOADED',
  MODEL_NOT_FOUND: 'MODEL_NOT_FOUND',
  UNKNOWN_MODEL: 'MODEL_NOT_FOUND',
};

const STATUS_SIGNALS: Record<number, AppErrorCode> = {
  401: 'AUTH_INVALID',
  402: 'BILLING',
  403: 'PERMISSION',
  408: 'TIMEOUT',
  429: 'RATE_LIMIT',
  503: 'OVERLOADED',
  504: 'TIMEOUT',
  529: 'OVERLOADED',
};

export function mapBackendErrorCode(code?: string): AppErrorCode {
  if (typeof code !== 'string') return 'UNKNOWN';
  return CODE_SIGNALS[code.trim().toUpperCase()] ?? 'UNKNOWN';
}

/**
 * Last-resort classification from the untranslated technical message.
 * Only reachable when no structured signal identified a class.
 */
function classifyMessage(message: string): AppErrorCode {
  // Separator-insensitive so `invalid_api_key` / `rate_limit_exceeded` style
  // provider tokens match the same probes as prose.
  const lower = message.toLowerCase().replace(/[_-]+/g, ' ');

  if (
    lower.includes('invalid ipc channel')
    || lower.includes('no handler registered')
    || lower.includes('window is not defined')
    || lower.includes('unsupported')
  ) {
    return 'CHANNEL_UNAVAILABLE';
  }
  if (lower.includes('conversation state') || lower.includes('roles must alternate')) {
    return 'CONVERSATION_STATE';
  }
  if (
    lower.includes('insufficient balance')
    || lower.includes('insufficient_quota')
    || lower.includes('insufficient quota')
    || lower.includes('quota exceeded')
    || lower.includes('exceeded your current quota')
    || lower.includes('billing')
    || lower.includes('credit balance')
    || lower.includes('payment required')
  ) {
    return 'BILLING';
  }
  if (
    lower.includes('invalid api key')
    || lower.includes('api key is invalid')
    || lower.includes('api key was revoked')
    || lower.includes('key has been revoked')
  ) {
    return 'AUTH_PERMANENT';
  }
  if (
    lower.includes('invalid authentication')
    || lower.includes('unauthorized')
    || lower.includes('auth failed')
    || lower.includes('401')
  ) {
    return 'AUTH_INVALID';
  }
  if (lower.includes('model not found') || lower.includes('unknown model')) {
    return 'MODEL_NOT_FOUND';
  }
  if (lower.includes('overloaded')) {
    return 'OVERLOADED';
  }
  if (lower.includes('timeout') || lower.includes('timed out') || lower.includes('abort')) {
    return 'TIMEOUT';
  }
  if (lower.includes('rate limit') || lower.includes('429')) {
    return 'RATE_LIMIT';
  }
  if (
    lower.includes('permission')
    || lower.includes('forbidden')
    || lower.includes('denied')
    || lower.includes('403')
  ) {
    return 'PERMISSION';
  }
  if (
    lower.includes('network')
    || lower.includes('fetch')
    || lower.includes('econnrefused')
    || lower.includes('econnreset')
    || lower.includes('enotfound')
  ) {
    return 'NETWORK';
  }
  if (lower.includes('gateway')) {
    return 'GATEWAY';
  }
  if (lower.includes('config') || lower.includes('invalid') || lower.includes('validation') || lower.includes('400')) {
    return 'CONFIG';
  }

  return 'UNKNOWN';
}

function readStringField(source: Record<string, unknown>, key: string): string | undefined {
  const value = source[key];
  if (typeof value === 'string' && value.trim()) return value.trim();
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  return undefined;
}

function readStatusField(source: Record<string, unknown>, key: string): number | undefined {
  const value = source[key];
  const parsed = typeof value === 'number'
    ? value
    : (typeof value === 'string' && /^\d+$/.test(value.trim()) ? Number(value.trim()) : Number.NaN);
  if (!Number.isFinite(parsed) || parsed < 100 || parsed > 599) return undefined;
  return parsed;
}

/** Walks the error and its nested cause/response/data chain once. */
function collectSignalSources(err: unknown): Array<Record<string, unknown>> {
  const sources: Array<Record<string, unknown>> = [];
  const seen = new Set<unknown>();
  const visit = (value: unknown): void => {
    if (!value || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);
    const record = value as Record<string, unknown>;
    sources.push(record);
    visit(record.cause);
    visit(record.error);
    visit(record.response);
    visit(record.data);
  };
  visit(err);
  return sources;
}

/**
 * Reads structured signals, most explicit source first: caller-supplied
 * `details` (host-api envelopes, store context) then the throwing object and
 * its nested cause/response chain.
 */
export function readErrorSignals(err: unknown, details?: Record<string, unknown>): ErrorSignals {
  const sources = [...(details ? [details] : []), ...collectSignalSources(err)];
  const signals: ErrorSignals = {};
  for (const source of sources) {
    signals.code ??= readStringField(source, 'code')
      ?? readStringField(source, 'errorCode')
      ?? readStringField(source, 'reasonCode');
    signals.status ??= readStatusField(source, 'status')
      ?? readStatusField(source, 'statusCode')
      ?? readStatusField(source, 'httpStatus');
    signals.reason ??= readStringField(source, 'reason')
      ?? readStringField(source, 'type')
      ?? readStringField(source, 'errorType');
  }
  return signals;
}

function classifySignals(signals: ErrorSignals): AppErrorCode | undefined {
  for (const token of [signals.code, signals.reason]) {
    if (!token) continue;
    const mapped = mapBackendErrorCode(token);
    if (mapped !== 'UNKNOWN') return mapped;
  }
  return signals.status !== undefined ? STATUS_SIGNALS[signals.status] : undefined;
}

function readErrorMessage(err: unknown): string {
  if (err instanceof Error) return err.message;
  if (err && typeof err === 'object') {
    return readStringField(err as Record<string, unknown>, 'message') ?? '';
  }
  return err === undefined || err === null ? '' : String(err);
}

export function normalizeAppError(err: unknown, details?: Record<string, unknown>): AppError {
  if (err instanceof AppError) {
    const requestId = err.requestId
      ?? readStringField(err.details ?? {}, 'requestId');
    return new AppError(
      err.code,
      err.message,
      err.cause ?? err,
      { ...(err.details ?? {}), ...(details ?? {}) },
      requestId,
    );
  }

  const message = readErrorMessage(err);
  const signals = readErrorSignals(err, details);
  // Structured signals win. Only their absence lets the untranslated technical
  // message (or a structured `reason` string) decide the class.
  const code = classifySignals(signals)
    ?? classifyMessage([signals.reason ?? '', message].join(' ').trim());
  return new AppError(
    code,
    message,
    err,
    details,
    readStringField(details ?? {}, 'requestId'),
  );
}
"},{"path":"harness/specs/tasks/harness-gap-error-recovery-next-action.md","content":"# G01：错误恢复与受约束的下一步操作

## 目标

为统一错误模型中的每个 `AppErrorCode` 提供稳定、可审计的恢复策略。每个 `AppError` 都携带 `retryable` 和 `nextAction`，但恢复建议只能是声明式的固定动词与有界目标，不能携带可执行内容。

## 行为契约

- `APP_ERROR_RECOVERY` 是唯一的恢复策略表，类型覆盖全部 `AppErrorCode`，新增错误码时必须同步增加表项。
- `scope` 为 `self` 时，应用可以在当前请求边界内自行恢复；`scope` 为 `user` 时，需要用户完成相应操作。
- 只有 `self` 范围且可安全重试的错误标记为 `retryable: true`，其动作严格为 `{ kind: 'retry' }`。
- 非重试错误的 `scope` 均为 `user`，且动作不得为 `retry`。
- 允许的动词只有 `retry`、`reauthenticate`、`reconfigure`、`open-settings`、`contact-support`。
- 动作对象只能包含 `kind`，以及该动词对应的有界 `target`。`target` 必须取自类型声明中的固定集合。
- `UNKNOWN` 不提供动作。它仍保留原始 `message` 和 `cause`，由既有统一错误出口向用户暴露原始错误，不伪造可自动修复的结论。
- 错误继续使用既有 `HostResponse` / `AppError` envelope，不引入平行错误类型。

## 恢复表

| 错误码 | retryable | scope | nextAction |
| --- | --- | --- | --- |
| `AUTH_INVALID` | false | user | `reauthenticate / authentication` |
| `AUTH_PERMANENT` | false | user | `reauthenticate / authentication` |
| `TIMEOUT` | true | self | `retry` |
| `RATE_LIMIT` | true | self | `retry` |
| `PERMISSION` | false | user | `open-settings / permissions` |
| `CHANNEL_UNAVAILABLE` | true | self | `retry` |
| `CONVERSATION_STATE` | false | user | `reconfigure / conversation` |
| `NETWORK` | true | self | `retry` |
| `CONFIG` | false | user | `reconfigure / configuration` |
| `GATEWAY` | true | self | `retry` |
| `BILLING` | false | user | `contact-support / billing` |
| `OVERLOADED` | true | self | `retry` |
| `MODEL_NOT_FOUND` | false | user | `reconfigure / model` |
| `UNKNOWN` | false | user | 无；暴露原始错误 |

## 验收检查

1. 枚举 `APP_ERROR_CODES` 并确认每个元素在 `APP_ERROR_RECOVERY` 中恰有一个表项。
2. 确认所有 `retryable: true` 表项的 `scope` 为 `self`，动作严格等于 `{ kind: 'retry' }`。
3. 确认所有 `retryable: false` 表项的 `scope` 为 `user`，且动作不是 `retry`。
4. 确认 `AppError` 实例具有 `retryable`，并在存在表项动作时具有 `nextAction`。
5. 确认 `UNKNOWN.nextAction` 不存在，同时原始消息与原因仍可用于统一错误展示。
6. 确认动作动词、目标集合和动作键均受限，且没有可执行字段。
7. 运行现有错误治理检查以及定向测试、web 类型检查、scoped lint、harness validate/dry-run、comms replay/compare 和凭据扫描。
"},{"path":"docs/dev/harness-gap-closure/g01-error-recovery-next-action.md","content":"# G01 错误恢复与下一步操作闭环

## 背景

原先错误分类能够稳定地产生 `AppErrorCode`，但错误实例没有统一的恢复属性，调用方只能根据错误码分散判断。此闭环在既有 `HostResponse` / `AppError` envelope 内增加稳定恢复策略，不改变错误分类与统一出口。

## 设计

`src/lib/error-model.ts` 导出以下契约：

- `AppErrorNextAction`：固定动词的判别联合；仅 `retry` 没有目标，其余动作带固定枚举 `target`。
- `AppErrorRecovery`：包含 `retryable`、`scope` 和可选 `action`。
- `APP_ERROR_RECOVERY`：以 `Record<AppErrorCode, AppErrorRecovery>` 约束的完整恢复表。
- `AppError.retryable`：直接来自当前错误码的稳定表项。
- `AppError.nextAction`：复制当前错误码的表项动作；`UNKNOWN` 不设置该属性。

恢复权限分为：

- `self`：应用可以在请求边界内执行恢复，仅用于瞬时且可安全重试的错误。
- `user`：需要用户完成认证、修改设置、调整配置或联系支持。

## 安全边界

恢复动作是 UI/宿主可以解释的结构化意图，不是可执行内容。动作只允许以下动词：

- `retry`
- `reauthenticate`
- `reconfigure`
- `open-settings`
- `contact-support`

`target` 只能从类型中声明的认证、对话、配置、模型、账单和权限等固定值中选择。动作对象只允许 `kind` 与可选的固定 `target`，不接受任意参数、用户输入或可执行片段。

## UNKNOWN 行为

未知错误不能被推测为可重试。`UNKNOWN` 的策略是不可重试、用户范围且没有动作。规范化过程仍保留原始 `message`、`cause` 和可用的 `details`，因此统一错误出口可以向用户暴露原始错误并供诊断使用，而不会声称存在自动修复。

## 策略摘要

| 错误码 | retryable | scope | 动作 |
| --- | --- | --- | --- |
| `AUTH_INVALID` | false | user | 重新认证 |
| `AUTH_PERMANENT` | false | user | 重新认证 |
| `TIMEOUT` | true | self | 重试 |
| `RATE_LIMIT` | true | self | 重试 |
| `PERMISSION` | false | user | 打开权限设置 |
| `CHANNEL_UNAVAILABLE` | true | self | 重试 |
| `CONVERSATION_STATE` | false | user | 调整对话配置 |
| `NETWORK` | true | self | 重试 |
| `CONFIG` | false | user | 调整配置 |
| `GATEWAY` | true | self | 重试 |
| `BILLING` | false | user | 联系账单支持 |
| `OVERLOADED` | true | self | 重试 |
| `MODEL_NOT_FOUND` | false | user | 调整模型选择 |
| `UNKNOWN` | false | user | 无，暴露原始错误 |

## 验证

实现应满足以下不变量：

- 恢复表覆盖全部错误码且无遗漏。
- 仅 `self` 范围的重试类具有 `retryable: true`，其动作严格为 `{ kind: 'retry' }`。
- 其余错误均为 `user` 范围且不提供重试动作。
- `AppError` 的恢复属性只由稳定表派生，调用方不能通过详情字段改变权限范围或动作。
- `UNKNOWN` 没有 `nextAction`，但原始错误信息保持可用。
- 既有错误治理、统一 envelope、测试、权限与依赖配置保持不变。
"}]}

