  | 'UNKNOWN';

/**
 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** Who is permitted to perform the recovery represented by an error class. */
export type ErrorRecoveryScope = 'self' | 'user';

/**
 * A recovery is a closed, declarative vocabulary. Targets identify a bounded
 * settings area; they never contain user-provided or executable instructions.
 */
export type AppErrorNextAction =
  | { kind: 'retry' }
  | { kind: 'reauthenticate'; target: 'authentication' }
  | { kind: 'reconfigure'; target: 'configuration' | 'conversation' | 'model' }
  | { kind: 'open-settings'; target: 'billing' | 'permissions' }
  | { kind: 'contact-support'; target: 'billing' | 'configuration' };

export type AppErrorRecovery = {
  retryable: boolean;
  scope: ErrorRecoveryScope;
  action?: AppErrorNextAction;
};

/**
 * Stable recovery policy for every error class.
 *
 * The type makes omissions a compile-time error. Only transient classes that
 * can safely be retried by the application are self-scoped and retryable.
 * UNKNOWN deliberately has no action: its original message and cause remain
 * available to the unified error renderer for diagnosis.
 */
export const APP_ERROR_RECOVERY = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'user',
    action: { kind: 'open-settings', target: 'permissions' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
